import{_ as E,C as o,o as r,c as h,j as d,a,b as i,w as e,E as n,a2 as s,a3 as b}from"./chunks/framework.C51MRPOx.js";const _=JSON.parse('{"title":"记忆系统","description":"","frontmatter":{},"headers":[],"relativePath":"智能体设计/记忆系统.md","filePath":"智能体设计/记忆系统.md","lastUpdated":null}'),p={name:"智能体设计/记忆系统.md"};function B(A,t,C,m,u,f){const l=o("Mermaid");return r(),h("div",null,[t[1]||(t[1]=d("h1",{id:"记忆系统",tabindex:"-1"},[a("记忆系统 "),d("a",{class:"header-anchor",href:"#记忆系统","aria-label":'Permalink to "记忆系统"'},"​")],-1)),t[2]||(t[2]=d("p",null,"模型的上下文窗口会在一轮结束后丢掉，也会在对话变长时装不下更早的内容。所以记忆放在模型外面，由运行时保管。模型负责决定「要不要查、查到的内容怎么用」；运行时负责保存、过期、检索，并且只把查到的那几条交回去。",-1)),t[3]||(t[3]=d("p",null,"本文说明记住什么、存在哪、如何读写、谁可以看见。某一轮提示词里具体怎么摆放这些内容，是另一套装配规则，这里不展开。",-1)),t[4]||(t[4]=d("h2",{id:"对话记忆分三层",tabindex:"-1"},[a("对话记忆分三层 "),d("a",{class:"header-anchor",href:"#对话记忆分三层","aria-label":'Permalink to "对话记忆分三层"'},"​")],-1)),t[5]||(t[5]=d("p",null,"三层对应三种寿命。往上越接近模型，越短、越完整；往下越适合跨会话，越只留值得记住的事实。",-1)),(r(),i(s,null,{default:e(()=>[n(l,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20WM%5B%22%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BF%86%3Cbr%2F%3E%E8%BF%9B%E7%A8%8B%E5%86%85%20%C2%B7%20%E6%9C%80%E8%BF%91%E8%8B%A5%E5%B9%B2%E8%BD%AE%E5%8E%9F%E6%96%87%22%5D%20--%3E%7C%22%E8%BD%AE%E6%AC%A1%E6%8C%A4%E5%87%BA%22%7C%20SB%5B%22%E7%9F%AD%E6%9C%9F%E7%BC%93%E5%86%B2%3Cbr%2F%3E%E7%BC%93%E5%AD%98%20%C2%B7%20%E6%8C%89%E7%94%A8%E6%88%B7%2F%E8%AE%BE%E5%A4%87%E5%88%86%22%5D%0A%20%20%20%20SB%20--%3E%7C%22%E8%BF%81%E5%87%BA%E5%90%8E%E6%8A%BD%E5%8F%96%22%7C%20LT%5B%22%E9%95%BF%E6%9C%9F%E4%BA%8B%E5%AE%9E%3Cbr%2F%3E%E5%81%8F%E5%A5%BD%20%C2%B7%20%E5%86%B3%E5%AE%9A%20%C2%B7%20%E7%BA%A6%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=b('<table tabindex="0"><thead><tr><th>层</th><th>存放</th><th>内容</th><th>寿命与迁出</th></tr></thead><tbody><tr><td>工作记忆</td><td>进程内</td><td>最近若干轮的原文，供紧接着的下一句使用</td><td>有轮次上限，超限的轮次被挤出，进缓冲或压缩成更短记录；进程重启后以磁盘和缓冲为准重新装入</td></tr><tr><td>短期缓冲</td><td>进程外缓存，按用户和设备分开</td><td>挤出的轮次、一段时间积累的对话</td><td>轮次达上限或距上次写入超时，满足任一即迁出：交给长期记忆做抽取，不永久留下原文；条目带过期时间</td></tr><tr><td>长期事实</td><td>持久存储，按用户+智能体标识</td><td>偏好、决定、稳定情况、未完成的约定</td><td>按当前问题检索，返回少数几条相关事实，不是全部历史；不保存每一句寒暄的原文</td></tr></tbody></table><p>三层的方向是单向提升：原文先留在工作记忆，挤出后进缓冲，缓冲再被抽取成事实。事实不会反向写成完整对话。</p><h2 id="文件式的另一种做法" tabindex="-1">文件式的另一种做法 <a class="header-anchor" href="#文件式的另一种做法" aria-label="Permalink to &quot;文件式的另一种做法&quot;">​</a></h2><p>同一件事也可以不经过向量库，而放在工作区的文件里。适合单用户、由智能体自己维护笔记的场合。</p><table tabindex="0"><thead><tr><th>材料</th><th>内容</th><th>更新方式</th></tr></thead><tbody><tr><td>长期偏好</td><td>已确认的偏好和重要事实；稳定、短、允许被修订</td><td>智能体用写文件工具更新，人也可以直接改；可与系统提示词里的「服务对象」是同一份材料</td></tr><tr><td>会话原文</td><td>按日期归档，一天一个文件：时间、用户原话、助手回复</td><td>由运行时在每一轮结束后追加，不依赖模型记得去写</td></tr></tbody></table><p>读取时不要把这些文件整份放进提示，步骤是：</p><ol><li>按当前问题在偏好说明和归档目录里搜索，得到命中的文件和位置；</li><li>只读取命中位置附近的若干行；</li><li>把这几行交给模型。</li></ol><p>模型决定要查什么，运行时执行搜索和切片。模型没有「假装已经记住全部归档」的义务，也没有把整个目录读进来的必要。</p><p>向量长期记忆和文件笔记可以同时存在：向量库存从对话里抽出的事实，适合按语义找回「上次说过的偏好」；文件归档保存原话，适合找回某一次具体怎么说的；偏好说明是给人读、也给每一轮直接看见的那一小份稳定事实。</p><h2 id="短时模态" tabindex="-1">短时模态 <a class="header-anchor" href="#短时模态" aria-label="Permalink to &quot;短时模态&quot;">​</a></h2><p>情绪、画面、本轮临时事项，寿命比对话更短，不能写进长期事实。</p><table tabindex="0"><thead><tr><th>模态</th><th>存放</th><th>规则</th></tr></thead><tbody><tr><td>情绪</td><td>按设备和用户存放最近几次判断，带过期时间</td><td>连续几次接近，才把它当成当前情绪；过期后当作没有</td></tr><tr><td>画面</td><td>只在感知通道里保留最近若干帧</td><td>供需要看图的那一次使用；帧不进入对话原文</td></tr><tr><td>临时事项</td><td>本轮抽出、预计很快过期的条目，例如「此刻站在哪个区域」</td><td>有条数上限和过期时间，到期删除</td></tr></tbody></table><p>这些状态回答的是「现在怎样」；长期事实回答的是「这个人一直是怎样」。把情绪和画面写进长期库，下一周的对话会读到过期的现场。</p><h2 id="写什么" tabindex="-1">写什么 <a class="header-anchor" href="#写什么" aria-label="Permalink to &quot;写什么&quot;">​</a></h2><p>一轮结束时，运行时把这一轮追加到工作记忆，并按规则考虑是否迁出。长期事实的写入看价值，不看字数：</p><table tabindex="0"><thead><tr><th>值得留下</th><th>不写入</th></tr></thead><tbody><tr><td>用户明确表达的偏好和限制</td><td>寒暄、重复的确认</td></tr><tr><td>已经做出的决定</td><td>只在这一分钟成立的状态</td></tr><tr><td>还没做完的约定</td><td>模型自己的推测（要留，须在后续对话里被用户确认后再写入）</td></tr><tr><td>以后换一天仍然成立的事实</td><td>—</td></tr></tbody></table><p>定时任务和心跳使用独立的短会话，它们的提示和回复不追加进日常聊天档案。否则每小时一次的巡检会把日常记录冲满，检索时也会把巡检话术当成用户说过的话。</p><h2 id="谁能读到" tabindex="-1">谁能读到 <a class="header-anchor" href="#谁能读到" aria-label="Permalink to &quot;谁能读到&quot;">​</a></h2><p>记忆按范围隔离。检索时带上范围，不靠提示词提醒模型「请勿泄露」：</p><table tabindex="0"><thead><tr><th>范围</th><th>规则</th></tr></thead><tbody><tr><td>长期事实</td><td>同时按用户和智能体过滤；一台设备上的对话默认不取另一台设备为同一人写下的记录，需要共享时显式放宽</td></tr><tr><td>归档与工作记忆</td><td>跟会话走；日常会话和某一次定时任务是不同会话，互不把原文混在一起</td></tr><tr><td>个人长期记忆</td><td>只进入与该用户的直接会话；群聊、多人在场的共享场合不注入，共享场合只能用这个场合自己的会话记录和故意写成可公开的资料</td></tr><tr><td>短时模态</td><td>键包含设备标识；设备断开或超时后，情绪和画面一并失效，不留给下一位用户</td></tr></tbody></table><p>模型可以要求检索，但不能要求运行时把某个范围之外的库整份交出来。范围是查询参数，由运行时填写，不由模型在对话里改写。</p>',21))])}const F=E(p,[["render",B]]);export{_ as __pageData,F as default};
